%%
diaryPatterns = ["my dorm","friend dorm","community","stairs","elev","hall","kitchen","bath","llc","mezz","other","outside","lounge"]';
diaryPatternLabels = ["My Dorm", "Friend Dorm", "Comm. Assembly", "Stairs", "Elevator", "Hall", "Kitchen", "Bathroom", "LLC Lounge", "Mezzanine", "Other", "Outside", "Lounge"];
time_list = ["8am","12pm","4pm","8pm","12am"];

% sum every diary in diary list
diary_sum = zeros(size(diaries{1}));
for i = 1:length(diaries)
    diary_sum = diary_sum + diaries{i};
end
% normalize the sum
diary_sum_normalized = diary_sum/max(diary_sum,[],"all");

% Create "heat map" of diaries; how often are students in certain patterns
figure
imagesc(diary_sum_normalized)
title("Diaries heat map")
set(gca,"ytick",1:length(diaryPatterns),"YTickLabel",diaryPatternLabels)
set(gca,"xtick",[16 32 48 64 80],"XTickLabel",time_list)
hold on
for xt = get(gca, "XTick")
    plot([xt xt], ylim, "k--", "LineWidth", 1); % Draw dashed line at each xtick
end
hold off
colorbar

%%
% Finding average time spent in pattern (averaging over all students) with
% std

timeSpentInPatterns = zeros(length(diaries),size(diaries{1},1));

for i = 1:length(diaries)
    for j = 1:size(diaries{1},2)
        timeSpentMin = 15*diaries{i}(:,j)/sum(diaries{i}(:,j));
        if isnan(timeSpentMin)
            disp("error at diary " + i + " col " + j)
        else
            timeSpentInPatterns(i,:) = timeSpentInPatterns(i,:) + timeSpentMin'/60;
        end
    end
end

% various statistical things of the diary data
colSums = sum(timeSpentInPatterns,1);
meanTSIP = mean(timeSpentInPatterns);
stdTSIP = std(timeSpentInPatterns);
rangeTSIP = range(timeSpentInPatterns);

% total pattern usage by all students (not average)
figure
bar(colSums)
xticklabels(diaryPatternLabels)
title('Total time spent by students in patterns')
xlabel('Patterns')
ylabel('Total hours')
ylim([0 600])
grid on

% avg pattern usage by students w error bars
% Create a bar plot of meanTSIP with stdTSIP as error bars
figure
bar(meanTSIP/24)
hold on
errorbar(1:length(meanTSIP), meanTSIP/24, stdTSIP/24, 'k', 'linestyle', 'none', "LineWidth",1)
set(gca, 'XTickLabel', diaryPatternLabels)
xlabel('Patterns',"FontSize",20)
ylabel('Portion of total time spent',"FontSize",20)
ylim([0 0.8])
title('Distribution of usage across patterns',"FontSize",23)
grid on
hold off

% Define the patterns of interest
patterns_of_interest = ["bath", "stairs", "hall", "community", "elev"];
pattern_indices = ismember(diaryPatterns, patterns_of_interest);

% Extract the relevant data
filtered_meanTSIP = meanTSIP(pattern_indices);
filtered_stdTSIP = stdTSIP(pattern_indices);
filtered_patterns = diaryPatterns(pattern_indices);

% Sort the data from min to max
[sorted_meanTSIP, sort_order] = sort(filtered_meanTSIP);
sorted_stdTSIP = filtered_stdTSIP(sort_order);
sorted_patterns = filtered_patterns(sort_order);
sorted_patterns = ["Stairs","Comm. Assembly", "Elevators", "Hallways", "Bathrooms"];
% Create a bar plot of sorted meanTSIP with stdTSIP as error bars
figure
bar(sorted_meanTSIP/24)
hold on
errorbar(1:length(sorted_meanTSIP), sorted_meanTSIP/24, sorted_stdTSIP/24, 'k', 'linestyle', 'none')
set(gca, 'XTickLabel', sorted_patterns)
xlabel('Patterns')
ylabel('Portion of total time spent)')
ylim([0 2])
title('Distribution of usage across patterns')
grid on
hold off


%% Need to find average wake up time

% Find time step when student first leaves rooms
total = 0;
for i = 1:length(diaries)
    j=1;
    while sum(diaries{i}(2:end,j))==0
        j=j+1;
    end
    total = total+j;
end
t0 = round(total/length(diaries));
disp(t0)
% average wake up time (time when student first leaves their room) is
% 8:15-8:30am, i.e., time step 18
%%

early_morning_diaries = cell(length(diaries),1);
for i = 1:length(diaries)
    early_morning_diaries{i} = diaries{i}(:,3:18);
end

morning_diaries = cell(length(diaries),1);
for i = 1:length(diaries)
    morning_diaries{i} = diaries{i}(:,19:34);
end

afternoon_diaries = cell(length(diaries),1);
for i = 1:length(diaries)
    afternoon_diaries{i} = diaries{i}(:,35:50);
end

early_evening_diaries = cell(length(diaries),1);
for i = 1:length(diaries)
    early_evening_diaries{i} = diaries{i}(:,51:65);
end

late_evening_diaries = cell(length(diaries),1);
for i = 1:length(diaries)
    late_evening_diaries{i} = diaries{i}(:,67:82);
end

night_diaries = cell(length(diaries),1);
for i = 1:length(diaries)
    night_diaries{i} = [diaries{i}(:,83:96) diaries{i}(:,1:2)];
end

save('diaries.mat','diaries','diaryPatterns','early_morning_diaries','morning_diaries','afternoon_diaries','early_evening_diaries','late_evening_diaries','night_diaries')

